pub struct Aggregator {
    /// GROUP BY expressions.
    group_by: Vec<Expression>,
    /// Aggregates to compute.
    aggregates: Vec<Aggregate>,
    /// Accumulators indexed by group_by bucket.
    buckets: BTreeMap<Vec<Value>, Vec<Accumulator>>,
}

impl Aggregator {
    /// Creates a new aggregator for the given GROUP BY buckets and aggregates.
    pub fn new(group_by: Vec<Expression>, aggregates: Vec<Aggregate>) -> Self {
        Self {
            group_by,
            aggregates,
            buckets: BTreeMap::new(),
        }
    }

    /// Adds a row to the aggregator.
    pub fn add(&mut self, row: &Row) -> Result<()> {
        let bucket: Vec<Value> = self.group_by
            .iter()
            .map(|expr| expr.evaluate(Some(row)))
            .collect::<Result<_>>()?;

        let entry = self.buckets.entry(bucket).or_insert_with(|| {
            self.aggregates.iter().map(|_| Accumulator::new(&Aggregate::Count(Expression::Constant(Value::Null)))).collect()
        });

        for (i, agg) in self.aggregates.iter().enumerate() {
            if i < entry.len() {
                entry[i].add(agg.expr().evaluate(Some(row))?)?;
            }
        }

        Ok(())
    }

    /// Adds rows to the aggregator.
    pub fn add_rows(&mut self, rows: Rows) -> Result<()> {
        for row in rows {
            self.add(&row?)?;
        }
        Ok(())
    }

    /// Returns a row iterator over the aggregate result.
    pub fn into_rows(self) -> Rows {
        let mut rows = Vec::new();
        for (bucket, accumulators) in self.buckets {
            let mut row = Vec::new();
            for val in bucket {
                row.push(val);
            }
            for acc in accumulators {
                row.push(acc.value().unwrap_or(Value::Null));
            }
            rows.push(row);
        }
        Box::new(rows.into_iter().map(Ok))
    }
}

/// Accumulates aggregate values.
#[derive(Clone)]
enum Accumulator {
    Average { count: i64, sum: Value },
    Count(i64),
    Max(Option<Value>),
    Min(Option<Value>),
    Sum(Option<Value>),
    Median(Vec<Value>),
    StringAgg { values: Vec<String>, delimiter: String },
}

impl Accumulator {
    /// Creates a new accumulator from an aggregate kind.
    fn new(aggregate: &Aggregate) -> Self {
        match aggregate {
            Aggregate::Average(_) => Accumulator::Average { count: 0, sum: Value::Integer(0) },
            Aggregate::Count(_) => Accumulator::Count(0),
            Aggregate::Max(_) => Accumulator::Max(None),
            Aggregate::Min(_) => Accumulator::Min(None),
            Aggregate::Sum(_) => Accumulator::Sum(None),
            Aggregate::Median(_) => Accumulator::Median(Vec::new()),
            Aggregate::StringAgg(_, _) => Accumulator::StringAgg { values: Vec::new(), delimiter: ",".to_string() },
        }
    }

    /// Adds a value to the accumulator.
    fn add(&mut self, value: Value) -> Result<()> {
        match self {
            Accumulator::Average { count, sum } => {
                *count += 1;
                *sum = sum.checked_add(&value)?;
            }
            Accumulator::Count(c) => {
                *c += 1;
            }
            Accumulator::Max(max) => {
                if value > *max.as_ref().unwrap_or(&Value::Null) {
                    *max = Some(value);
                }
            }
            Accumulator::Min(min) => {
                if value < *min.as_ref().unwrap_or(&Value::Null) {
                    *min = Some(value);
                }
            }
            Accumulator::Sum(sum) => {
                match sum {
                    Some(s) => *sum = Some(s.checked_add(&value)?),
                    None => *sum = Some(value),
                }
            }
            Accumulator::Median(values) => {
                values.push(value);
            }
            Accumulator::StringAgg { values, delimiter } => {
                if let Value::String(s) = value {
                    values.push(s);
                }
            }
        }
        Ok(())
    }

    /// Returns the aggregate value.
    fn value(self) -> Result<Value> {
        match self {
            Accumulator::Average { count, sum } => {
                if count == 0 {
                    Ok(Value::Null)
                } else {
                    Ok(sum.checked_div(&Value::Integer(count))?)
                }
            }
            Accumulator::Count(c) => Ok(Value::Integer(c)),
            Accumulator::Max(m) => Ok(m.unwrap_or(Value::Null)),
            Accumulator::Min(m) => Ok(m.unwrap_or(Value::Null)),
            Accumulator::Sum(s) => Ok(s.unwrap_or(Value::Integer(0))),
            Accumulator::Median(mut values) => {
                if values.is_empty() {
                    Ok(Value::Null)
                } else {
                    values.sort();
                    let mid = values.len() / 2;
                    if values.len() % 2 == 0 {
                        let v1 = &values[mid - 1];
                        let v2 = &values[mid];
                        match (v1, v2) {
                            (Value::Integer(a), Value::Integer(b)) => Ok(Value::Integer((a + b) / 2)),
                            (Value::Float(a), Value::Float(b)) => Ok(Value::Float((a + b) / 2.0)),
                            _ => Ok(Value::Null),
                        }
                    } else {
                        Ok(values[mid].clone())
                    }
                }
            }
            Accumulator::StringAgg { values, delimiter } => {
                Ok(Value::String(values.join(&delimiter)))
            }
        }
    }
}
